using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BDAudit {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");string root=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string h=root+"/SourceAssets/B2_DetailMezzanine/",o=root+"/Docs/Review/2026-11-10_B2_DetailMezzanine/";var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var byId=ts.ToDictionary(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString());var old=JArray.Parse(File.ReadAllText(h+"before.json"));var missing=old.Where(p=>!byId.ContainsKey((string)p["id"])).Select(p=>(string)p["name"]).ToArray();var moved=old.Where(p=>byId.ContainsKey((string)p["id"])&&Vector3.Distance(byId[(string)p["id"]].position,new Vector3((float)p["position"][0],(float)p["position"][1],(float)p["position"][2]))>.001f).Select(p=>(string)p["name"]).ToArray();var nodes=ts.Where(t=>t.name.StartsWith("B2_")).Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t.name,position=new[]{t.position.x,t.position.y,t.position.z},active=t.gameObject.activeInHierarchy}).ToArray();File.WriteAllText(o+"unity_final_state.json",JsonConvert.SerializeObject(nodes,Formatting.Indented));var result=new{scene=s.path,saved=!s.isDirty,oldTransforms=old.Count,missing,moved,activeLights=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).Count(),reflectionProbes=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>()).Count(),newMissingMeshes=ts.Where(t=>t.name.StartsWith("BD_")).SelectMany(t=>t.GetComponents<MeshFilter>()).Count(m=>!m.sharedMesh),newMissingMaterials=ts.Where(t=>t.name.StartsWith("BD_")).SelectMany(t=>t.GetComponents<MeshRenderer>()).Sum(m=>m.sharedMaterials.Count(a=>!a))};File.WriteAllText(o+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
